"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["54326"],{8990(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.precedencia_fase.aresta_duplicada","status":422,"titulo":"J\xe1 existe uma aresta de preced\xeancia viva com este par de fases"},"descricao":{"codigo":"uniplus.configuracao.precedencia_fase.aresta_duplicada","requisitos":[],"oQueAconteceu":["O cadastro de uma preced\xeancia (`POST /api/configuracao/admin/precedencias-fase`) trouxe um par de fases, antecessora e sucessora, que j\xe1 est\xe1 cadastrado entre as preced\xeancias existentes. O par \xe9 a identidade da preced\xeancia: o mesmo par duas vezes n\xe3o acrescenta nada aas preced\xeancias cadastradas. O par inverso, com as fases trocadas, n\xe3o \xe9 duplicata e tem outra recusa (ver `uniplus.configuracao.precedencia_fase.ciclo_detectado`).","A confer\xeancia de duplicata vem depois das confer\xeancias dos c\xf3digos e antes da de ciclo. Duas requisi\xe7\xf5es simult\xe2neas com o mesmo par tamb\xe9m terminam nesta recusa: a que confirma por \xfaltimo a recebe. A resposta traz o c\xf3digo de erro e a mensagem, sem a lista `errors`. Nada \xe9 gravado."],"comoResolver":["N\xe3o \xe9 preciso cadastrar de novo: a preced\xeancia j\xe1 vale. Para mudar se os per\xedodos das duas fases podem se sobrepor, atualize a preced\xeancia existente (`PUT /api/configuracao/admin/precedencias-fase/{id}`); ela \xe9 localizada na listagem (`GET /api/configuracao/precedencias-fase`). S\xf3 esse atributo \xe9 edit\xe1vel: para trocar o par de fases, remova a preced\xeancia e cadastre outra."],"ondeAparece":["Cadastro de uma preced\xeancia entre fases"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Precedencia fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);